from ..data_layer.msg_rake_ir import RakeIRInterface


class MeasurementsPublicInterface(object):

    def __init__(self, connection):
        self.connection = connection

    def get_rtt_value(self, cell_id):
        """
        Initialize IR measurements and return the round-trip time value (RTT)
        """
        return RakeIRInterface(self.connection).get_rtt_value(cell_id)
